class AurenCourse{final String id,title,description,category,teacherId,level;final List<String> skills;final int lessonCount;final DateTime? createdAt;const AurenCourse({required this.id,required this.title,required this.description,required this.category,required this.teacherId,required this.skills,required this.lessonCount, this.level,this.createdAt});factory AurenCourse.fromMap(String id,Map<String,dynamic> d)=>AurenCourse(id:id,title:d['title']??'',description:d['description']??'',category:d['category']??'General',teacherId:d['teacherId']??'',level:d['level']??'All',skills:d['skills'] is List ? List<String>.from(d['skills']).take(20).toList() : const [],lessonCount:(d['lessonCount'] as num?)?.toInt()??0,createdAt:(d['createdAt'] as Timestamp?)?.toDate());}
class AurenLearningProgress{final String courseId;final int completedLessons;final bool enrolled;const AurenLearningProgress({required this.courseId,required this.completedLessons,required this.enrolled});}